{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol, a highly lipophilic aromatic lignan, had absolute oral bioavailability of approximately 2% in patients, well below the 20% threshold, supporting low F for large lipophilic aromatic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Eliglustat, a lipophilic basic amide with a benzodioxole, showed simulated absolute oral bioavailability of 0.086, supporting low F for complex lipophilic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Halofantrine, the closest structural analogue with a dibutylamino alcohol on a chlorinated polycyclic aromatic, is reported to have low and erratic oral bioavailability in humans and animals, supporting low F for the similarly lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A retrospective absolute-bioavailability estimate for halofantrine in fasted humans was approximately 30%, above the 20% threshold; this single estimate is contradictory but is outweighed by multiple qualitative low-bioavailability reports and the query's even more lipophilic, chlorinated fluorene core.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Terbutaline, a small polar beta-agonist, had absolute oral bioavailability of about 14.8%, below 20%, showing that even relatively small molecules can have low F due to presystemic clearance.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Prochlorperazine, a lipophilic basic phenothiazine, had absolute oral bioavailability of about 5.7%, supporting low F for lipophilic basic amines with extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Curcumin, a lipophilic polyphenol, has low oral bioavailability in humans due to poor solubility and rapid metabolism, supporting low F for highly lipophilic aromatic compounds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is lumefantrine, a highly lipophilic, poorly water-soluble fluorene amino alcohol. All high-transfer experimental analogues have oral bioavailability below 20% (mostly 2-15%), and the closest structural analogue halofantrine is predominantly reported as low/erratic; the single ~30% estimate is an outlier and the query's even more lipophilic chlorinated core is expected to have F<20%. Prediction: low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for lumefantrine in the provided evidence; closest analogue halofantrine has mixed quantitative/qualitative data.",
    "Food effects and formulation dependence are not captured in the threshold decision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

